from ute_ue.lteue import LteUe
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer


class DataTransfer(LteDataTransfer):
    def __int__(self, dt):
        self.__dt = dt

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        return self.__dt.start()

    def stop(self, should_raise: bool = True):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :param should_raise: Allow to raise an exception or rather to log warning
        :return: None
        """
        return self.__vc.stop(should_raise)

    def await_finish(self):
        """
        Waits until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        return self.__dt.await_finish()

    def is_running(self):
        """
        Checks if both client and server are running:
        App Server: checks if paramiko connection has command exit status
        UE: checks if data transfer on UEPC is in active state
        Check is skipped if data transfer earlier was stopped, False is returned immediately
        :return: boolean
        """
        return self.__dt.is_running()

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""
        return self.__dt.check_data_transfer()

    def get_data_transfer_statistics(self, **kwargs):
        """
        Get data transfer statistics
        :param omit: The delay in seconds to start counting the tput
                     ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: The end time in seconds to stop counting the tput
                    ex. '40' - it takes into account data till 40 second of transfer.
        :return: Statistics formatted into string like "{avg_thr},{min_thr},{max_thr};{bandwidths}"
        :raises DataTransferStatisticsError: None of bandwidth rows received
        :raises DataTransferException: Invalid omit/end is given
        """
        return self.__dt.get_data_transfer_statistics(**kwargs)

    def get_average_throughput(self, **kwargs):  # noqa: C901
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or
        from 'dt.start()' to 'dt.stop()' if data transfer is already finished or
        with currently available iperf intervals that were already transferred.

        :param omit: it is a delay in seconds to start counting the throughput
                     ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the throughput
                    ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: Kbits/sec
        """
        return self.__dt.get_average_throughput(**kwargs)

    def release_resources(self):
        """
        Releases data transfer resources for APP server. There is no need to release UE resources here because it is
        done on taf.ue.proxy level.
        """
        return self.__dt.release_resources()

    def __getattr__(self, item):
        attr = getattr(self.__dt, item)
        return attr


class Ue(LteUe):
    def __init__(self, ue):
        self.__ue = ue

    @property
    def id(self):
        return self.__ue.ue_id

    @property
    def ip(self):
        return self.__ue.ue_ip

    def create_data_transfer(self, name: str, **kwargs) -> DataTransfer:
        """
        Create Data Transfer instance for MediaTek UE.

        :param name: str: Data Transfer Alias name
        :return: Instance of data transfer
        """
        return self.__ue.create_data_transfer(name, **kwargs)

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        return self.__ue.prepare_ue()

    def attach(self, timeout=3, **kwargs):
        """
        Perform attach on UE.

        :param timeout: Time during which UE should finish attach procedure(change attach state and connect to cell)
        :param kwargs: UE specific arguments
        :return: None
        """
        return self.__ue.attach(timeout=timeout, **kwargs)

    def detach(self, timeout=3, **kwargs):
        """
        Perform detach on UE.
        No action if UE is already detached.

        :param timeout: Time during which UE should perform detach
        :param kwargs: UE specific arguments
        :return: None
        """
        return self.__ue.detach(timeout=timeout, **kwargs)

    def get_ue_info(self, info_list=None):
        """
        Get specified UE information.
        Available `info_type` values are:
            'NAME' - `device` UE info from `adb devices -l` command
            'SERIAL' - UE serial number
            'OS_VERSION' - MediaTek UE version(e.g. Petrus, Figeac, Dujac)
            'BUILD_VERSION' - UE firmware version, equivalent of `adb shell getprop ro.build.id`
            'DEVICE_MODEL' - UE device model
            'IMSI' - IMSI number on UE
            'IMEI' - IMEI number on UE
            'IP' - UE ip info at some point
            'IPS' - returns a dict of apn_name and its ip addresses both v4 and v6;
                    e.g. {"dxdata1": ["100.99.250.145"],
                          "wap1.nokia.com": ["192.168.1.47"]}

        :param info_list: info(s) to be returned, None by default, it means 'ALL'.
                          It may be one (string) or more than one (list) of following infos, None by default.
        :return: string value for single info; dict {'info_name': 'info_value'} for multiple info
        """
        return self.__ue.get_ue_info(info_list=info_list)

    def reboot(self, timeout: int = 120):
        """
        Reboot UE and wait until it is fully functional.

        :param timeout - waiting time in seconds for ue after reboot
        :return: None
        """
        return self.__ue.reboot(timeout=timeout)

    def change_deployment_mode(self, deployment_mode):
        """
        Change deployment mode.

        :param str deployment_mode: Deployment mode option
        """
        return self.__ue.change_deployment_mode(deployment_mode)

    def get_deployment_mode(self):
        """
        Detect deployment mode.
        :return: deployment mode
        :rtype: str
        """
        return self.__ue.get_deployment_mode()

    def create_default_pdn(self):
        """
        Create default PDN on UE.
        """
        return self.__ue.create_default_pdn()

    def connect_additional_pdn(self, pdn):
        """
        Establish additional default bearer.

        :param str pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: UE ip from additional PDN
        """
        return self.__ue.connect_additional_pdn(pdn=pdn)

    def disconnect_additional_pdn(self, pdn):
        """
        Release additional default bearer.

        :param str pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: None
        """
        return self.__ue.disconnect_additional_pdn(pdn=pdn)

    def switch_to_pdu_session(self, pdn_name):
        """
        Switch to PDU session by PDN name
        """
        return self.__ue.switch_to_pdu_session(pdn_name=pdn_name)

    def get_data_transfer_raw_data(self, dt_name, output_file=None):
        """Get all raw statistics of data transfer final result"""
        return self.__ue.get_data_transfer_raw_data(dt_name=dt_name, output_file=output_file)

    def create_log_view(self, name, log_type='ota'):
        """
        Create log view
        :param name: Log name
        :param log_type: Default value is "ota"
        """
        return self.__ue.create_log_view(name=name, log_type=log_type)

    def read_latest_log(self, log_view):
        """
        Read the latest log list
        :param log_view: log view instance
        """
        return self.__ue.read_latest_log(log_view=log_view)

    def read_log_until(self, log_view, expected, timeout=5):
        """
        Read log list until expected value detected
        :param log_view: log view instance
        :param expected: expected value
        :param timeout: default value of timeout is 5 seconds
        """
        return self.__ue.read_log_until(log_view, expected, timeout)
